"""Unified LLM judge interface for pointwise and pairwise evaluation.

Each judge wraps an API (OpenAI, Anthropic, Google, DeepSeek, OpenRouter, vLLM)
and returns a standardized score dict. Supports both MT-Bench-style pointwise
scoring and Arena-Hard-style pairwise comparison.

Env vars: OPENAI_API_KEY, ANTHROPIC_API_KEY, GOOGLE_API_KEY,
          DEEPSEEK_API_KEY, OPENROUTER_API_KEY
"""

import os
import re
from abc import ABC, abstractmethod

POINTWISE_JUDGE_PROMPT = """\
Please act as an impartial judge and evaluate the quality of the response provided by an AI assistant to the user question displayed below. Rate the response on a scale of 1 to 10, where 1 is the worst and 10 is the best. Consider factors such as helpfulness, relevance, accuracy, depth, creativity, and level of detail. Begin your evaluation by providing a short explanation. Be as objective as possible. After providing your explanation, output your rating strictly following this format: "[[rating]]", for example: "[[5]]".

[Question]
{prompt}

[The Start of Assistant's Answer]
{response}
[The End of Assistant's Answer]"""

PAIRWISE_JUDGE_PROMPT = """\
Please act as an impartial judge and evaluate the quality of the responses \
provided by two AI assistants to the user question displayed below. You should \
choose the assistant that follows the user's instructions and answers the \
user's question better. Your evaluation should consider factors such as the \
helpfulness, relevance, accuracy, depth, creativity, and level of detail of \
their responses. Begin your evaluation by comparing the two responses and \
provide a short explanation. Avoid any position biases and ensure that the \
order in which the responses were presented does not influence your decision. \
Do not allow the length of the responses to influence your evaluation. Do not \
favor certain names of the assistants. Be as objective as possible. After \
providing your explanation, output your final verdict by strictly following \
this format: "[[A]]" if assistant A is better, "[[B]]" if assistant B is \
better, and "[[C]]" for a tie.

[User Question]
{prompt}

[The Start of Assistant A's Answer]
{response_a}
[The End of Assistant A's Answer]

[The Start of Assistant B's Answer]
{response_b}
[The End of Assistant B's Answer]"""


def _parse_verdict(raw: str) -> float | None:
    """Extract pairwise verdict. Returns 1.0/0.0/0.5/None."""
    match = re.search(r"\[\[([ABC])\]\]", raw)
    if not match:
        return None
    v = match.group(1)
    if v == "A":
        return 1.0
    elif v == "B":
        return 0.0
    return 0.5


def _parse_pointwise_score(raw: str) -> float | None:
    """Extract pointwise rating [[N]] where N in 1-10. Returns float or None."""
    match = re.search(r"\[\[(\d+(?:\.\d+)?)\]\]", raw)
    if not match:
        return None
    score = float(match.group(1))
    if 1 <= score <= 10:
        return score
    return None


class JudgeInterface(ABC):
    """Base class for all LLM judges."""

    @abstractmethod
    def evaluate(self, prompt: str, response_a: str, response_b: str,
                 swap_position: bool = False) -> dict:
        """Pairwise evaluation.

        Returns:
            {score: float|None, raw_output: str, position: "AB"|"BA"}
            score: 1.0=A wins, 0.0=B wins, 0.5=tie, None=parse failure
        """
        pass

    @abstractmethod
    def evaluate_pointwise(self, prompt: str, response: str) -> dict:
        """Pointwise evaluation (1-10 scale).

        Returns:
            {score: float|None (1-10), raw_output: str}
        """
        pass

    def _build_prompt(self, prompt: str, response_a: str, response_b: str,
                      swap_position: bool) -> tuple[str, str]:
        if swap_position:
            text = PAIRWISE_JUDGE_PROMPT.format(
                prompt=prompt, response_a=response_b, response_b=response_a)
            return text, "BA"
        else:
            text = PAIRWISE_JUDGE_PROMPT.format(
                prompt=prompt, response_a=response_a, response_b=response_b)
            return text, "AB"

    def _build_pointwise_prompt(self, prompt: str, response: str) -> str:
        return POINTWISE_JUDGE_PROMPT.format(prompt=prompt, response=response)

    def _make_result(self, raw_output: str, position: str) -> dict:
        score = _parse_verdict(raw_output)
        if score is not None and position == "BA":
            score = 1.0 - score
        return {"score": score, "raw_output": raw_output, "position": position}

    def _make_pointwise_result(self, raw_output: str) -> dict:
        score = _parse_pointwise_score(raw_output)
        return {"score": score, "raw_output": raw_output}


class OpenAIJudge(JudgeInterface):
    """Judge using OpenAI API (GPT-4o, GPT-5.5)."""

    def __init__(self, model_name: str, api_key: [REDACTED] = None):
        from openai import OpenAI
        self.model_name = model_name
        self.client = OpenAI(api_key=[REDACTED] or os.environ["OPENAI_API_KEY"])

    def _call(self, text: str) -> str:
        resp = self.client.chat.completions.create(
            model=self.model_name,
            messages=[{"role": "user", "content": text}],
            temperature=0.0,
            max_tokens=1024,
        )
        return resp.choices[0].message.content

    def evaluate(self, prompt, response_a, response_b, swap_position=False):
        text, position = self._build_prompt(prompt, response_a, response_b, swap_position)
        return self._make_result(self._call(text), position)

    def evaluate_pointwise(self, prompt, response):
        text = self._build_pointwise_prompt(prompt, response)
        return self._make_pointwise_result(self._call(text))


